def exact(i,o,c):
    H,W=len(i),len(i[0])
    ci=sorted((y,x) for y in range(H) for x in range(W) if i[y][x]==c)
    co=sorted((y,x) for y in range(H) for x in range(W) if o[y][x]==c)
    if len(ci)!=len(co): return None
    used=[False]*len(ci); pairs=[]
    for r in range(len(ci)):
        best=None
        for k in range(len(co)):
            d=abs(ci[r][0]-co[k][0])+abs(ci[r][1]-co[k][1])
            if not used[k] and (best is None or d<best[0]): best=(d,k)
        d,k=best
        used[k]=True; pairs.append((ci[r],co[k]))
    return pairs
