            if any(y>=H or x>=W or a[y][x]!=bgv for y,x in dset): continue
            # adjacency to other objects in OUTPUT (before update) minus own original cells
            occ=set()
            for j,t in enumerate(objs):
                if j==si: continue
                tcells={p for p in t if p not in s}
                occ|=tcells
            if any(out[y][x]!=bgv for y,x in dset if (y,x) not in s) or any(out[y][x-1] != bgv for y,x in s if out[y][x]!=bgv): 
                pass
            if any(out[yy][xx] != bgv for yy,xx in dset if (yy,xx) not in s): continue
            # also no new vertical adjacency
            if any(out[yy][xx]==bgv for yy,xx in dset): pass
            # forbidden: shifted cell becomes orthogonally adjacent to another object's cell in output (excluding own orig pos)
            if any(out[yy][xx]!=bgv for yy,xx in dset if (yy,xx) not in s): continue
