# Hypothesis: cell stays iff its bottom-left diagonal neighbor (in input or current) is occupied by same object color.
# Iterate: snapshot = A; for every non-bg cell (y,x), if bgv at A[y][x+1] OR y==H-1: move. Else stay.
def f(inp):
    A=np.array(inp); H,W=A.shape
    bgv=int(collections.Counter(A.flatten()).most_common(1)[0][0])
    o=A.copy()
    for iter_ in range(H+2):
