                if c==bgv: continue
                tg=(yy,xx+1)
                if int(A[tg[0]][tg[1]])==bgv:
                    o[tg[0]][tg[1]]=c; o[yy][xx]=bgv; moved=True
        if not moved: break
    return o.tolist()
